import "github.com/egoist/mygo/ui"

// Icons from Remix Icon 4.6 (apache.org/licenses/LICENSE-2.0), drawn on a
// 24-point grid in the color of the text: a coherent set whose line
// weights agree whatever the corner of the app they stand in.

// remixIcon wraps the body of a Remix Icon: every glyph of the set is a
// filled shape on the 24-point grid, the line weights and roundings of
// which the set keeps alike across its thousand icons.
func remixIcon(body string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor">` + body + `</svg>`))
}

